-- Nạp quiz chuẩn bị tối trước BUỔI 12 (CNC lớp đảo ngược): 5 câu, đọc trước Ôn quy trình và an toàn (Bài 4T–6).
-- Soạn từ Ôn quy trình lập kế hoạch gia công và an toàn chung: Bài 4T mục 2, 10; Bài 5 mục 3, 5; Bài 6 mục 5.
-- Không ghi đè nếu thầy đã đăng prep-12 qua /quan-tri/cnc-dang-de (on conflict do nothing).
-- Lưu ý: trigger trg_exams_sync_bank chép câu vào question_bank như mọi ngân hàng CNC khác.
-- Rollback: delete from public.exams where cnc_key = 'prep-12';
insert into public.exams (title, duration_minutes, published, questions, topic, difficulty, cnc_key)
values ('Chuẩn bị buổi 12 — Dự án nhóm', 20, false, '[{"type": "multiple_choice", "question": "Trước khi cấp điện, em thấy chìa khóa mâm cặp còn nằm trên bàn dao. Xử lý thế nào?", "options": ["Cấp điện, về Reference xong mới cất", "Để nguyên, vì trục chính chưa quay thì chưa sao", "Lấy ra, cất đúng chỗ rồi mới cấp điện", "Đóng cửa che chắn lại là đủ an toàn"], "answer": 2, "explanation": "Bài 4T mục 2: vùng quay và vùng hành trình phải trống trước khi cấp điện; lúc về Reference các trục đã tự chạy và có thể kẹp, hất vật lạ."}, {"type": "multiple_choice", "question": "Năm bước giải bài gia công tổng hợp theo đúng thứ tự là:", "options": ["Tính tọa độ → đọc bản vẽ → chọn gốc W → xếp thứ tự → kiểm tra", "Đọc bản vẽ → xếp thứ tự → tính tọa độ → chọn gốc W → kiểm tra", "Chọn gốc W → tính tọa độ → đọc bản vẽ → kiểm tra → xếp thứ tự", "Đọc bản vẽ → chọn gốc W → xếp thứ tự → tính tọa độ → kiểm tra"], "answer": 3, "explanation": "Bài 5 mục 5: đọc bản vẽ → gốc W → thứ tự → tọa độ → kiểm tra. Chưa có W thì chưa tính được tọa độ."}, {"type": "multiple_choice", "question": "Nguyên tắc sắp thứ tự nguyên công phay nào đúng?", "options": ["Tinh trước, thô sau để giữ mặt chuẩn đẹp", "Gia công trọn trong một lần gá để W không đổi; thô trước, tinh sau; gom nguyên công cùng dao", "Tarô trước, khoan sau cho ren đều", "Gá lại phôi sau mỗi nguyên công cho chắc"], "answer": 1, "explanation": "Bài 6 mục 5: một lần gá để W không đổi; thô trước tinh sau; gom cùng dao; khoan trước, tarô sau."}, {"type": "multiple_choice", "question": "Cài xong W và offset dao, lần đầu chạy thử trên máy nên làm thế nào?", "options": ["Chạy tự động 100% vì đã mô phỏng trên Win-NC32", "Chạy tự động nhưng mở cửa che chắn để nhìn rõ", "Chạy MDI từng khối, bước tiến thấp; lệch tọa độ hoặc sắp va chạm thì dừng ngay", "Bỏ qua vì về Reference xong là máy đã đúng"], "answer": 2, "explanation": "Bài 4T mục 10: kiểm tra bằng MDI, từng khối, bước tiến thấp; lệch là dừng, rút dao, kiểm lại offset."}, {"type": "multiple_choice", "question": "Trên chi tiết tiện có rãnh và ren. Hai nguyên công này làm vào lúc nào?", "options": ["Sau cùng, khi đường kính đã đạt", "Trước tiện thô, để làm chuẩn", "Ngay sau tiện mặt đầu", "Sau khi đã cắt đứt chi tiết"], "answer": 0, "explanation": "Bài 5 mục 3: tiện ren, rãnh làm sau cùng khi đường kính đã đạt; đo kiểm rồi mới cắt đứt hoặc tháo phôi."}]'::jsonb, 'CNC', '', 'prep-12')
on conflict (cnc_key) do nothing;
